MATCH (c1:Country)-[:hasDiplomaticRelationWith]->(c2:Country)
WHERE EXISTS {
  MATCH (c2)-[:hasDiplomaticRelationWith]->(:Country {name: "Romania"})
}
RETURN c1.name, count(DISTINCT c2) AS related_country_count

MATCH (c1:Country)-[:hasDiplomaticRelationWith]->(c2:Country)
WHERE EXISTS {
  MATCH (c2)-[:hasHeadOfState]->(:Politician)
}
UNWIND c1.official_language AS language
RETURN DISTINCT language

CALL {
  MATCH (p:Politician {name: "Per-Samuel Nissr"})-[:holdsPosition]->(pos:Position)
  RETURN pos
}
WITH DISTINCT pos
RETURN count(pos)

MATCH (c:Country {name: "Rwanda"})-[:hasHeadOfState]->(p:Politician)
WHERE NOT EXISTS {
  MATCH (c)-[r:hasHeadOfState]->(p)
  WHERE r.end_year IS NOT NULL AND r.end_year <= date().year
}
RETURN DISTINCT p.name

MATCH (c:Country {name: "Belarus"})-[:hasHeadOfState]->(p:Politician)
WHERE NOT EXISTS {
  MATCH (c)-[r:hasHeadOfState]->(p)
  WHERE r.end_year IS NOT NULL AND r.end_year < date().year
}
RETURN DISTINCT p.name

MATCH (c:Country {name: "Sudan"})-[:hasHeadOfGovernment]->(p:Politician)
WHERE NOT EXISTS {
  MATCH (c)-[r:hasHeadOfGovernment]->(p)
  WHERE r.end_year IS NOT NULL AND r.end_year <= date().year
}
RETURN DISTINCT p.name

MATCH (p:Politician)-[:memberOf]->(pp:PoliticalParty)
WHERE EXISTS {
  MATCH (pp2:PoliticalParty {name: "The Republicans"})-[:headedBy]->(p)
}
RETURN pp.name, count(DISTINCT p) AS politician_count
